Ext.define('bcp.view.RequestDashViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.requestsdashview',

    onRefresh: function (tool, e, owner, eOpts) {
        this.getReferences().list.store.load();
    },

    onSelect: function (rowmodel, record, index, eOpts) {
        var reqId = record.get('requestId'),
            component = this.getView();
        //send users to the detail page based on the type of request
        if (component.viewType == 'pendingrequests') {
            this.redirectTo('#pendingrequests/' + reqId);
        } else if (component.viewType == 'requesttracking') {
            this.redirectTo('#requesttracking/' + reqId);
        } else if (component.viewType == 'savedrequests') {
            this.redirectTo('#newrequest/' + reqId);
        } else if (component.viewType == 'archivedrequests') {
            this.redirectTo('#historicalrequests/' + reqId);
        } else if (component.viewType == 'preparedrequests') {
            this.redirectTo('#preparedrequests/' + reqId);
        }
    },

    onPanelAdded: function (component, container, pos, eOpts) {
        var store = this.getStore('store');

        store.clearFilter();

        //depend on the view type, customize it
        if (component.viewType == 'pendingrequests') {
            component.setTitle('Pending Actions');
            store.proxy.url = '/empbc/v1/requests/pending';
        } else if (component.viewType == 'requesttracking') {
            component.setTitle('My Submitted Requests');
            store.proxy.url = '/empbc/v1/requests/submitted';
            store.addFilter({
                operator: '!=',
                property: 'statusCode',
                value: 10
            });
        } else if (component.viewType == 'savedrequests') {
            component.setTitle('My Saved Requests');
            store.proxy.url = '/empbc/v1/requests/saved';
        } else if (component.viewType == 'archivedrequests') {
            component.setTitle('My Received Requests');
            store.proxy.url = '/empbc/v1/requests/archived';
        } else if (component.viewType == 'preparedrequests') {
            component.setTitle('Requests Prepared by Me');
            store.proxy.url = '/empbc/v1/requests/prepared';
        }
        store.load();
    },

    onPanelBeforeClose: function (panel, eOpts) {
        //when a subview is closed by the user, update the setting in localstorage
        var store = Ext.getStore('DashSettings'),
            arr = store.first().get('subviews');

        for (var i = 0; i <= arr.length; i++) {
            if (arr[i] === panel.reference) {
                arr.splice(i, 1);
            }
        }
        store.sync();
    }
});
